input.oninput:
this.value = this.value.replace(/[^0-9]/g, '');
var fullVal = '+255' + this.value;
document.getElementById('nominee_mobile').value = fullVal;
var errDiv = document.getElementById('nominee_mobile_error');
if (this.value.length > 0 && !/^[67]/.test(this.value)) {
    if (errDiv) errDiv.style.display = 'block';
    this.classList.add('is-invalid');
} else {
    if (errDiv) errDiv.style.display = 'none';
    this.classList.remove('is-invalid');
}

template.script:

// Helper to set image globally
window.setImg = function(id, b64) {
    if (!b64) return;
    var el = document.getElementById(id);
    if (!el) return;
    var container = el.closest('.s_website_form_field');
    var img = container.querySelector('img');
    if (!img) {
        var div = document.createElement('div');
        div.className = "mt-2 text-center";
        img = document.createElement('img');
        img.style.maxHeight = "150px";
        img.style.border = "1px solid #ddd";
        img.style.padding = "5px";
        img.style.borderRadius = "4px";
        div.appendChild(img);
        container.appendChild(div);
    }
    img.src = "data:image/png;base64," + b64;

    // Remove required attribute from the file input since we have the base64 data
    el.removeAttribute('required');

    // Store the base64 string in a hidden input so it gets submitted with the form
    var hiddenInputId = id + '_b64';
    var hiddenInput = document.getElementById(hiddenInputId);
    if (!hiddenInput) {
        hiddenInput = document.createElement('input');
        hiddenInput.type = 'hidden';
        hiddenInput.id = hiddenInputId;
        hiddenInput.name = hiddenInputId;
        el.parentNode.appendChild(hiddenInput);
    }
    hiddenInput.value = b64;
};

document.addEventListener("DOMContentLoaded", function() {
    try {
        var nomRegionSelect = document.getElementById('nominee_region');
        var nomDistrictSelect = document.getElementById('nominee_district');
        var nomShehiaSelect = document.getElementById('nominee_shehia');
        var nomShehiaSearchInput = document.getElementById('nominee_shehia_search_input');
        var nomShehiaDropdownMenu = document.getElementById('nominee_shehia_dropdown_menu');
        var nomShehiaClearBtn = document.getElementById('nominee_shehia_clear_btn');
        var nomShehiaDropdownToggle = document.getElementById('nominee_shehia_dropdown_toggle');
        var nomCurrentActiveIndex = -1;

        if (!nomRegionSelect || !nomDistrictSelect) {
            return;
        }

        // Clone allowed options for districts
        var allNomDistricts = Array.from(nomDistrictSelect.options).map(function(opt) {
            return { 
                text: opt.text, 
                value: opt.value, 
                dCode: opt.getAttribute('data-district-code'),
                regionCode: opt.getAttribute('data-region-code')
            };
        });

        // Clone allowed options for shehias
        var allNomShehias = [];
        if (nomShehiaSelect) {
            allNomShehias = Array.from(nomShehiaSelect.options).map(function(opt) {
                return {
                    text: opt.text,
                    value: opt.value,
                    shehiaId: opt.getAttribute('data-shehia-id'),
                    districtId: opt.getAttribute('data-district-id'),
                    districtCode: opt.getAttribute('data-district-code'),
                    districtName: opt.getAttribute('data-district-name'),
                    regionId: opt.getAttribute('data-region-id'),
                    regionCode: opt.getAttribute('data-region-code')
                };
            });
        }

        function closeNomShehiaDropdown() {
            if (nomShehiaDropdownMenu) {
                nomShehiaDropdownMenu.style.display = 'none';
                nomCurrentActiveIndex = -1;
            }
        }

        function setNomActiveItem(idx, items) {
            if (!items || items.length === 0) return;
            items.forEach(function(el, i) {
                if (i === idx) {
                    el.style.backgroundColor = '#e9ecef';
                    el.scrollIntoView({ block: 'nearest' });
                } else if (nomShehiaSelect && nomShehiaSelect.value === el.getAttribute('data-value')) {
                    el.style.backgroundColor = '#e7f1ff';
                } else {
                    el.style.backgroundColor = '#fff';
                }
            });
            nomCurrentActiveIndex = idx;
        }

        function selectNomShehia(val) {
            if (nomShehiaSelect) nomShehiaSelect.value = val;
            if (nomShehiaSearchInput) {
                nomShehiaSearchInput.value = val;
                nomShehiaSearchInput.setCustomValidity('');
            }
            if (nomShehiaClearBtn) {
                nomShehiaClearBtn.style.display = val ? 'inline-block' : 'none';
            }
            closeNomShehiaDropdown();
            if (nomShehiaSelect) nomShehiaSelect.dispatchEvent(new Event('change'));
        }

        function isShehiaInDistrict(s, selectedDistVal) {
            if (!selectedDistVal) return false;
            var dist = selectedDistVal.trim().toLowerCase();
            return (
                (s.districtCode && s.districtCode.trim().toLowerCase() === dist) ||
                (s.districtId && String(s.districtId) === dist) ||
                (s.districtName && s.districtName.trim().toLowerCase() === dist)
            );
        }

        function renderNomShehiaDropdown(searchTerm) {
            if (!nomShehiaDropdownMenu) return;
            var term = (searchTerm || '').trim().toLowerCase();
            var selectedDistVal = nomDistrictSelect ? nomDistrictSelect.value : "";

            var matches = [];
            allNomShehias.forEach(function(s) {
                if (!s.value) return;
                if (!selectedDistVal || isShehiaInDistrict(s, selectedDistVal)) {
                    if (!term || s.text.toLowerCase().includes(term)) {
                        matches.push(s);
                    }
                }
            });

            nomShehiaDropdownMenu.innerHTML = '';
            nomCurrentActiveIndex = -1;

            if (!selectedDistVal) {
                var msg = document.createElement('div');
                msg.className = 'p-3 text-muted text-center';
                msg.innerHTML = '<small><i class="fa fa-info-circle me-1"></i>Please select a District first</small>';
                nomShehiaDropdownMenu.appendChild(msg);
            } else if (matches.length === 0) {
                var noMatch = document.createElement('div');
                noMatch.className = 'p-3 text-muted text-center';
                var b = document.createElement('b');
                b.textContent = searchTerm;
                noMatch.innerHTML = '<small><i class="fa fa-search me-1"></i>No Shehia found matching "</small>';
                noMatch.querySelector('small').appendChild(b);
                noMatch.querySelector('small').appendChild(document.createTextNode('"'));
                nomShehiaDropdownMenu.appendChild(noMatch);
            } else {
                matches.forEach(function(s, idx) {
                    var item = document.createElement('div');
                    item.className = 'nom-shehia-dropdown-item';
                    item.style.padding = '8px 14px';
                    item.style.cursor = 'pointer';
                    item.style.fontSize = '14px';
                    item.style.borderBottom = '1px solid #f2f2f2';
                    item.setAttribute('data-value', s.value);

                    if (nomShehiaSelect && nomShehiaSelect.value === s.value) {
                        item.style.backgroundColor = '#e7f1ff';
                        item.style.fontWeight = '600';
                        item.style.color = '#0d6efd';
                    }

                    if (term) {
                        var escaped = term.split('').map(function(c) { return /[.*+?^${}()|[\]\\]/.test(c) ? '\\' + c : c; }).join('');
                        var regex = new RegExp('(' + escaped + ')', 'gi');
                        var span = document.createElement('span');
                        span.textContent = s.text;
                        item.innerHTML = span.innerHTML.replace(regex, '<span style="background-color: #ffeeba; font-weight: bold; padding: 0 1px;">$1</span>');
                    } else {
                        item.textContent = s.text;
                    }

                    item.addEventListener('mouseenter', function() {
                        var allItems = nomShehiaDropdownMenu.querySelectorAll('.nom-shehia-dropdown-item');
                        setNomActiveItem(idx, allItems);
                    });

                    item.addEventListener('mousedown', function(e) {
                        e.preventDefault();
                        selectNomShehia(s.value);
                    });

                    nomShehiaDropdownMenu.appendChild(item);
                });
            }

            nomShehiaDropdownMenu.style.display = 'block';
        }

        if (nomShehiaSearchInput) {
            nomShehiaSearchInput.addEventListener('input', function() {
                var term = this.value;
                if (nomShehiaClearBtn) {
                    nomShehiaClearBtn.style.display = term ? 'inline-block' : 'none';
                }
                renderNomShehiaDropdown(term);
            });

            nomShehiaSearchInput.addEventListener('focus', function() {
                renderNomShehiaDropdown(this.value);
            });

            nomShehiaSearchInput.addEventListener('click', function() {
                renderNomShehiaDropdown(this.value);
            });

            nomShehiaSearchInput.addEventListener('keydown', function(e) {
                var items = nomShehiaDropdownMenu ? nomShehiaDropdownMenu.querySelectorAll('.nom-shehia-dropdown-item') : [];
                if (e.key === 'ArrowDown') {
                    e.preventDefault();
                    if (nomShehiaDropdownMenu && nomShehiaDropdownMenu.style.display === 'none') {
                        renderNomShehiaDropdown(this.value);
                        return;
                    }
                    if (items.length > 0) {
                        var next = (nomCurrentActiveIndex + 1) % items.length;
                        setNomActiveItem(next, items);
                    }
                } else if (e.key === 'ArrowUp') {
                    e.preventDefault();
                    if (items.length > 0) {
                        var prev = (nomCurrentActiveIndex - 1 + items.length) % items.length;
                        setNomActiveItem(prev, items);
                    }
                } else if (e.key === 'Enter') {
                    if (nomShehiaDropdownMenu && nomShehiaDropdownMenu.style.display !== 'none' && nomCurrentActiveIndex >= 0 && nomCurrentActiveIndex < items.length) {
                        e.preventDefault();
                        var val = items[nomCurrentActiveIndex].getAttribute('data-value');
                        selectNomShehia(val);
                    }
                } else if (e.key === 'Escape') {
                    closeNomShehiaDropdown();
                }
            });
        }

        if (nomShehiaDropdownToggle) {
            nomShehiaDropdownToggle.addEventListener('click', function(e) {
                e.preventDefault();
                if (nomShehiaDropdownMenu && nomShehiaDropdownMenu.style.display === 'block') {
                    closeNomShehiaDropdown();
                } else {
                    if (nomShehiaSearchInput) nomShehiaSearchInput.focus();
                    renderNomShehiaDropdown('');
                }
            });
        }

        if (nomShehiaClearBtn) {
            nomShehiaClearBtn.addEventListener('click', function(e) {
                e.preventDefault();
                selectNomShehia('');
                renderNomShehiaDropdown('');
                if (nomShehiaSearchInput) nomShehiaSearchInput.focus();
            });
        }

        document.addEventListener('click', function(e) {
            var container = document.getElementById('nominee_shehia_field_container');
            if (container && !container.contains(e.target)) {
                closeNomShehiaDropdown();
                if (nomShehiaSelect && nomShehiaSearchInput) {
                    if (nomShehiaSelect.value) {
                        nomShehiaSearchInput.value = nomShehiaSelect.value;
                        if (nomShehiaClearBtn) nomShehiaClearBtn.style.display = 'inline-block';
                    } else {
                        nomShehiaSearchInput.value = '';
                        if (nomShehiaClearBtn) nomShehiaClearBtn.style.display = 'none';
                    }
                }
            }
        });

        window.resetNomShehiaSearch = function() {
            if (nomShehiaSelect) nomShehiaSelect.value = '';
            if (nomShehiaSearchInput) {
                nomShehiaSearchInput.value = '';
                nomShehiaSearchInput.setCustomValidity('');
            }
            if (nomShehiaClearBtn) nomShehiaClearBtn.style.display = 'none';
            closeNomShehiaDropdown();
        };

        function filterNomShehias(preserveSelection) {
            if (!nomShehiaSelect) return;
            var selectedDistVal = nomDistrictSelect ? nomDistrictSelect.value : "";
            var currentShehiaVal = preserveSelection ? nomShehiaSelect.value : "";

            nomShehiaSelect.innerHTML = '';
            var defaultOpt = document.createElement('option');
            defaultOpt.value = "";
            defaultOpt.text = "Select Shehia";
            nomShehiaSelect.appendChild(defaultOpt);

            var matchingCount = 0;
            allNomShehias.forEach(function(s) {
                if (!s.value) return;
                if (!selectedDistVal || isShehiaInDistrict(s, selectedDistVal)) {
                    matchingCount++;
                    var opt = document.createElement('option');
                    opt.value = s.value;
                    opt.text = s.text;
                    opt.setAttribute('data-shehia-id', s.shehiaId);
                    opt.setAttribute('data-district-id', s.districtId);
                    opt.setAttribute('data-district-code', s.districtCode);
                    opt.setAttribute('data-district-name', s.districtName);
                    opt.setAttribute('data-region-id', s.regionId);
                    opt.setAttribute('data-region-code', s.regionCode);
                    if (currentShehiaVal && s.value === currentShehiaVal) {
                        opt.selected = true;
                    }
                    nomShehiaSelect.appendChild(opt);
                }
            });

            if (preserveSelection && currentShehiaVal) {
                selectNomShehia(currentShehiaVal);
            } else {
                if (nomShehiaSelect) nomShehiaSelect.value = '';
                if (nomShehiaSearchInput) {
                    nomShehiaSearchInput.value = '';
                    if (!selectedDistVal) {
                        nomShehiaSearchInput.placeholder = "Select District first...";
                    } else {
                        nomShehiaSearchInput.placeholder = "Type to search Shehia (" + matchingCount + " available)...";
                    }
                }
                if (nomShehiaClearBtn) nomShehiaClearBtn.style.display = 'none';
            }
            closeNomShehiaDropdown();
        }

        window.filterNomShehias = function() {
            filterNomShehias(false);
        };

        function filterNomDistricts() {
            var selectedVal = nomRegionSelect.value; // The value is the Code

            // Clear and Rebuild
            var currentVal = nomDistrictSelect.value;
            nomDistrictSelect.innerHTML = ''; // clear

            // Always add default Select option
            var defaultOpt = document.createElement('option');
            defaultOpt.value = "";
            defaultOpt.text = "Select";
            nomDistrictSelect.appendChild(defaultOpt);

            allNomDistricts.forEach(function(d) {
                if (d.value === "") return; // Skip original default

                // Filter logic: match district code in valid list
                if (!selectedVal || d.regionCode === selectedVal) {
                    var opt = document.createElement('option');
                    opt.value = d.value;
                    opt.text = d.text;
                    opt.setAttribute('data-district-code', d.dCode);
                    opt.setAttribute('data-region-code', d.regionCode);
                    if (d.value === currentVal) opt.selected = true;
                    nomDistrictSelect.appendChild(opt);
                }
            });

            filterNomShehias(false);
        }

        nomRegionSelect.addEventListener('change', filterNomDistricts);
        nomDistrictSelect.addEventListener('change', function() {
            filterNomShehias(false);
        });

        // Trigger initial
        if (nomRegionSelect.value) {
            filterNomDistricts();
        }
        if (nomDistrictSelect.value) {
            filterNomShehias(true);
        }

        // Form submit validation for Nominee Shehia
        var form = document.querySelector('form.s_website_form') || document.querySelector('form');
        if (form) {
            form.addEventListener('submit', function(e) {
                if (nomShehiaSearchInput && nomShehiaSelect) {
                    if (!nomShehiaSelect.value || nomShehiaSearchInput.value !== nomShehiaSelect.value) {
                        nomShehiaSearchInput.setCustomValidity('Please select a Shehia from the list');
                        nomShehiaSearchInput.reportValidity();
                        e.preventDefault();
                        return false;
                    } else {
                        nomShehiaSearchInput.setCustomValidity('');
                    }
                }
            });
        }

    } catch (e) {
        console.error("Nominee filter error", e);
    }
});


document.addEventListener("DOMContentLoaded", function() {
    var searchBtn = document.getElementById('nominee_zan_id_search');
    var zanInput = document.getElementById('nominee_zanid');
    var statusDiv = document.getElementById('nominee_zan_id_lookup_status');

    if (searchBtn) {
        searchBtn.addEventListener('click', function() {
            var zanId = zanInput.value;
            if (!zanId) {
                alert("Please enter a Nominee Zan ID");
                return;
            }

            var benefZanId = document.getElementById('benf_zan_id') ? document.getElementById('benf_zan_id').value : '';
            if (zanId && benefZanId && zanId.trim() === benefZanId.trim()) {
                statusDiv.innerText = "Nominee Zan ID and Beneficiary Zan ID cannot be the same.";
                statusDiv.style.color = "red";
                statusDiv.style.display = "block";
                return;
            }

            statusDiv.innerText = "Searching...";
            statusDiv.style.color = "blue";
            statusDiv.style.display = "block";

            fetch('/portal/registration/nominee_zan_id_lookup', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    params: {
                        nominee_zanid: zanId
                    }
                })
            })
            .then(response => response.json())
            .then(data => {
                var result = data.result;
                console.log("Nominee search result:", result);
                if (result && (result.status === 'SUCCESS' || result.status === 'ALREADY_EXISTS_BUT_FILL')) {

                    if (result.status === 'ALREADY_EXISTS_BUT_FILL') {
                        statusDiv.innerText = result.message;
                        statusDiv.style.color = "orange";
                    } else {
                        statusDiv.innerText = "Found!";
                        statusDiv.style.color = "green";
                    }

                    // Helper to safe set value
                    function setVal(id, val) {
                        if (id === 'nominee_mobile') {
                            var rawVal = val || '';
                            var visualVal = rawVal;
                            if (visualVal.startsWith('+255')) visualVal = visualVal.substring(4);
                            else if (visualVal.startsWith('255')) visualVal = visualVal.substring(3);
                            else if (visualVal.startsWith('0')) visualVal = visualVal.substring(1);

                            var visualEl = document.getElementById(id + '_visual');
                            if (visualEl) {
                                visualEl.value = visualVal;
                                visualEl.dispatchEvent(new Event('input'));
                            }

                            var hiddenVal = rawVal;
                            if (rawVal && !rawVal.startsWith('+255')) {
                                 if (rawVal.startsWith('255')) hiddenVal = '+' + rawVal;
                                 else if (rawVal.startsWith('0')) hiddenVal = '+255' + rawVal.substring(1);
                                 else hiddenVal = '+255' + rawVal;
                            }
                            var hiddenEl = document.getElementById(id);
                            if (hiddenEl) hiddenEl.value = hiddenVal;
                        } else {
                            var el = document.getElementById(id);
                            if (el) {
                                el.value = val || '';
                                el.dispatchEvent(new Event('change'));
                            }
                        }
                    }
                    function setSelect(id, val) {
                        var el = document.getElementById(id);
                        if (el && val) {
                            el.value = val;
                            el.dispatchEvent(new Event('change'));
                        }
                    }

                    setVal('nominee_first_name', result.nominee_first_name);
                    setVal('nominee_middle_name', result.nominee_middle_name);
                    setVal('nominee_last_name', result.nominee_last_name);
                    setVal('nominee_gender', result.nominee_gender);
                    setVal('nominee_mobile', result.nominee_mobile);
                    setVal('nominee_house_street', result.nominee_house_street);
                    setSelect('nominee_rel_benf', result.nominee_rel_benf);
                    setVal('nominee_post_code', result.nominee_post_code);

                    setSelect('nominee_region', result.nominee_region);
                    // Timeout for district
                    setTimeout(() => {
                        setSelect('nominee_district', result.nominee_district);
                        setImg('nominee_image', result.nominee_image);
                        if (typeof window.filterNomShehias === 'function') {
                            window.filterNomShehias();
                        }
                        // Ensure Nominee Shehia is left unselected for manual selection from filtered list
                        var nomShehiaEl = document.getElementById('nominee_shehia');
                        if (nomShehiaEl) nomShehiaEl.value = "";
                        var nomSearchInp = document.getElementById('nominee_shehia_search_input');
                        if (nomSearchInp) nomSearchInp.value = "";
                        var nomClear = document.getElementById('nominee_shehia_clear_btn');
                        if (nomClear) nomClear.style.display = 'none';
                    }, 120);

                } else {
                    statusDiv.innerText = (result && result.message) || "Not found";
                    statusDiv.style.color = "red";
                }
            })
            .catch(error => {
                console.error('Error:', error);
                statusDiv.innerText = "Error searching Nominee Zan ID";
                statusDiv.style.color = "red";
            });
        });
    }
});

div.script:
document.addEventListener("DOMContentLoaded", function() {
    var otherPensionSelect = document.getElementById('other_pension');
    var schemeContainer = document.getElementById('scheme_name_container');
    var hiddenInput = document.getElementById('scheme_name');
    var checkboxes = document.querySelectorAll('.scheme-checkbox');
    var selectedText = document.getElementById('schemeSelectedText');

    // 1. Conditional Visibility
    if (otherPensionSelect) {
        otherPensionSelect.addEventListener('change', function() {
            if (this.value === 'yes') {
                schemeContainer.style.display = 'block';
            } else {
                schemeContainer.style.display = 'none';
                // Optionally clear selection if "No" is selected
                checkboxes.forEach(cb => cb.checked = false);
                updateHiddenInput();
            }
        });
    }

    // 2. Multi-select logic
    function updateHiddenInput() {
        var selected = [];
        var hasOther = false;
        checkboxes.forEach(function(cb) {
            if (cb.checked) {
                if (cb.value === 'Other') {
                    hasOther = true;
                } else {
                    selected.push(cb.value);
                }
            }
        });

        var otherContainer = document.getElementById('scheme_other_input_container');
        var otherInput = document.getElementById('scheme_other_input');
        if (hasOther) {
            otherContainer.style.display = 'block';
            otherInput.setAttribute('required', 'required');
            var otherVal = otherInput.value.trim();
            if (otherVal) {
                selected.push('Other: ' + otherVal);
            } else {
                selected.push('Other');
            }
        } else {
            otherContainer.style.display = 'none';
            otherInput.removeAttribute('required');
            otherInput.value = ''; // Reset when unchecked
        }

        hiddenInput.value = selected.join(', ');

        if (selected.length === 0) {
            selectedText.innerText = 'Select Scheme';
        } else {
            selectedText.innerText = selected.join(', ');
        }
    }

    checkboxes.forEach(function(cb) {
        cb.addEventListener('change', updateHiddenInput);
    });

    var otherInput = document.getElementById('scheme_other_input');
    if (otherInput) {
        otherInput.addEventListener('input', updateHiddenInput);
    }

    // 3. Select All / Unselect All
    var selectAllBtn = document.getElementById('selectAllSchemes');
    var unselectAllBtn = document.getElementById('unselectAllSchemes');

    if (selectAllBtn) {
        selectAllBtn.addEventListener('click', function(e) {
            e.preventDefault();
            checkboxes.forEach(cb => cb.checked = true);
            updateHiddenInput();
        });
    }

    if (unselectAllBtn) {
        unselectAllBtn.addEventListener('click', function(e) {
            e.preventDefault();
            checkboxes.forEach(cb => cb.checked = false);
            updateHiddenInput();
        });
    }

    // Prevent dropdown from closing when clicking checkboxes or links
    var dropdownMenu = document.querySelector('.custom-multi-select .dropdown-menu');
    if (dropdownMenu) {
        dropdownMenu.addEventListener('click', function(e) {
            e.stopPropagation();
        });
    }

    // Initialize based on existing value
    if (hiddenInput && hiddenInput.value) {
        var vals = hiddenInput.value.split(',').map(s => s.trim());
        var otherVal = "";
        checkboxes.forEach(function(cb) {
            if (vals.includes(cb.value)) {
                cb.checked = true;
            }
        });

        // Check if any of the values start with "Other" or "Other: "
        var otherFound = vals.find(v => v === 'Other' || v.startsWith('Other: '));
        if (otherFound) {
            var cbOther = document.getElementById('scheme_other');
            if (cbOther) cbOther.checked = true;

            if (otherFound.startsWith('Other: ')) {
                otherVal = otherFound.substring(7); // Extract after "Other: "
            }
            if (otherInput) otherInput.value = otherVal;
        }
        updateHiddenInput();
    }
});

template.script:
document.getElementById('payment_mode').addEventListener('change', function() {
    var bankFields = document.getElementById('bank_fields');
    var walletFields = document.getElementById('wallet_fields');
    var isBank = (this.value === 'bank');
    var isWallet = (this.value === 'mobile_wallet');

    bankFields.style.display = isBank ? 'block' : 'none';
    walletFields.style.display = isWallet ? 'block' : 'none';

    // Clear irrelevant fields to prevent stale data
    if (!isBank) {
        document.getElementById('bank_name').value = '';
        document.getElementById('account_num').value = '';
        document.getElementById('account_name').value = '';
    }
    if (!isWallet) {
        document.getElementById('mobile_wallet').value = '';
    }
});

div.script:
(function() {
    var currentFieldId = null;
    var stream = null;
    var video = document.getElementById('webcamVideo');
    var canvas = document.getElementById('webcamCanvas');
    var webcamModalElem = document.getElementById('webcamModal');

    // Initialize bootstrap modal if it exists
    var modal = null;
    if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {
        modal = new bootstrap.Modal(webcamModalElem);
    }

    document.querySelectorAll('.open-cam').forEach(function(btn) {
        btn.addEventListener('click', function() {
            currentFieldId = this.getAttribute('data-field');
            navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } })
                .then(function(s) {
                    stream = s;
                    video.srcObject = stream;
                    if (modal) modal.show();
                    else if (window.jQuery && $(webcamModalElem).modal) $(webcamModalElem).modal('show');
                    else alert("Capture started. Please position yourself.");
                })
                .catch(function(err) {
                    alert("Could not access camera: " + err);
                });
        });
    });

    document.getElementById('snapPhoto').addEventListener('click', function() {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        canvas.getContext('2d').drawImage(video, 0, 0);

        canvas.toBlob(function(blob) {
            var file = new File([blob], currentFieldId + ".jpg", { type: "image/jpeg" });
            var container = new DataTransfer();
            container.items.add(file);
            document.getElementById(currentFieldId).files = container.files;
            document.getElementById(currentFieldId).dispatchEvent(new Event('change'));

            // Stop stream and hide
            stopCamera();
            if (modal) modal.hide();
            else if (window.jQuery && $(webcamModalElem).modal) $(webcamModalElem).modal('hide');
        }, 'image/jpeg');
    });

    function stopCamera() {
        if (stream) {
            stream.getTracks().forEach(function(track) { track.stop(); });
            stream = null;
        }
    }

    if (webcamModalElem) {
        webcamModalElem.addEventListener('hidden.bs.modal', function () {
            stopCamera();
        });
    }

    // File size validation and preview update
    const maxSizeBytes = 10 * 1024 * 1024; // 10MB
    ['beneficiary_image', 'nominee_image', 'zan_image'].forEach(function(id) {
        var input = document.getElementById(id);
        if (input) {
            input.addEventListener('change', function() {
                if (this.files && this.files[0]) {
                    var file = this.files[0];
                    if (file.size > maxSizeBytes) {
                        alert("The file size of the selected image exceeds 10MB. Please choose a smaller image.");
                        this.value = ''; // Clear the input
                        return;
                    }

                    // Update preview image
                    var container = this.closest('.s_website_form_field');
                    var img = container.querySelector('img');
                    if (!img) {
                        var div = document.createElement('div');
                        div.className = "mt-2 text-center";
                        img = document.createElement('img');
                        img.style.maxHeight = "150px";
                        img.style.border = "1px solid #ddd";
                        img.style.padding = "5px";
                        img.style.borderRadius = "4px";
                        div.appendChild(img);
                        container.appendChild(div);
                    }

                    var reader = new FileReader();
                    reader.onload = function(e) {
                        img.src = e.target.result;
                    };
                    reader.readAsDataURL(file);

                    // Clear the hidden base64 input since a new photo is chosen/captured
                    var hiddenInput = document.getElementById(id + '_b64');
                    if (hiddenInput) {
                        hiddenInput.value = "";
                    }
                }
            });
        }
    });
})();

input.oninput:
this.value = this.value.replace(/[^0-9]/g, '');
var fullVal = '+255' + this.value;
document.getElementById('mobile').value = fullVal;
var errDiv = document.getElementById('mobile_error');
if (this.value.length > 0 && !/^[67]/.test(this.value)) {
    errDiv.style.display = 'block';
    this.classList.add('is-invalid');
} else {
    errDiv.style.display = 'none';
    this.classList.remove('is-invalid');
}

template.script:
document.addEventListener("DOMContentLoaded", function() {
    var searchBtn = document.getElementById('zan_id_search');
    var zanInput = document.getElementById('benf_zan_id');
    var statusDiv = document.getElementById('zan_id_lookup_status');

    if (searchBtn) {
        searchBtn.addEventListener('click', function() {
            var zanId = zanInput.value;
            if (!zanId) {
                alert("Please enter a Zan ID");
                return;
            }

            statusDiv.innerText = "Searching...";
            statusDiv.style.color = "blue";
            statusDiv.style.display = "block";

            fetch('/portal/registration/zan_id_lookup', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    params: {
                        zan_id: zanId
                    }
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.result && data.result.status === 'SUCCESS') {
                    var result = data.result;

                    // Helper to safe set value
                    function setVal(id, val) {
                        if (id === 'mobile' || id === 'nominee_mobile') {
                            var rawVal = val || '';
                            // Strip prefix for visual input
                            var visualVal = rawVal;
                            if (visualVal.startsWith('+255')) {
                                visualVal = visualVal.substring(4);
                            } else if (visualVal.startsWith('255')) {
                                visualVal = visualVal.substring(3);
                            } else if (visualVal.startsWith('0')) {
                                visualVal = visualVal.substring(1);
                            }

                            var visualEl = document.getElementById(id + '_visual');
                            if (visualEl) {
                                visualEl.value = visualVal;
                                visualEl.dispatchEvent(new Event('input'));
                            }

                            // Ensure hidden input has full +255 format if not empty
                            var hiddenVal = rawVal;
                            if (rawVal && !rawVal.startsWith('+255')) {
                                 if (rawVal.startsWith('255')) hiddenVal = '+' + rawVal;
                                 else if (rawVal.startsWith('0')) hiddenVal = '+255' + rawVal.substring(1);
                                 else hiddenVal = '+255' + rawVal;
                            }
                            var hiddenEl = document.getElementById(id);
                            if (hiddenEl) hiddenEl.value = hiddenVal;
                        } else {
                             var el = document.getElementById(id);
                            if (el) {
                                el.value = val || '';
                                el.dispatchEvent(new Event('change'));
                            }
                        }
                    }

                    // Helper to safe set Select and trigger change
                    function setSelect(id, val) {
                        var el = document.getElementById(id);
                        if (el && val) {
                            el.value = val;
                            el.dispatchEvent(new Event('change'));
                        }
                    }

                    // Local setImg removed (using global window.setImg)

                     // 1. Basic Details
                     setVal('given_name', result.firstname);
                     setVal('middle_name', result.middle_name);
                     setVal('family_name', result.lastname);
                     setVal('birthdate', result.dob);
                     setVal('gender', result.gender);
                     setVal('mobile', result.mobile);

                     // Make retrieved official details read-only
                     ['given_name', 'middle_name', 'family_name', 'birthdate'].forEach(function(id) {
                         var el = document.getElementById(id);
                         if (el) el.readOnly = true;
                     });
                     var genderEl = document.getElementById('gender');
                     if (genderEl) {
                         genderEl.style.pointerEvents = 'none';
                         genderEl.style.backgroundColor = '#e9ecef';
                         genderEl.setAttribute('tabindex', '-1');
                     }

                    // 2. Address and Location
                    setVal('street', result.street);
                    setVal('benf_post_code', result.benf_post_code);
                    setSelect('ben_region', result.region);
                    // Timeout to allow region change to populate districts and filter shehias
                    setTimeout(() => {
                        setVal('ben_district', result.district);
                        if (typeof window.filterShehias === 'function') {
                            window.filterShehias();
                        }
                        // Ensure Shehia is left unselected for manual selection from filtered list
                        var shehiaEl = document.getElementById('street2');
                        if (shehiaEl) shehiaEl.value = "";
                        if (typeof window.resetShehiaSearch === 'function') {
                             window.resetShehiaSearch();
                        }
                    }, 120);
                    setVal('disability', result.disability);
                    setVal('type_of_disability', result.type_of_disability);
                    if (typeof toggleDisabilityType === 'function') toggleDisabilityType();

                    // 3. Allowance and Insurance
                    setVal('is_receiving_allowance', result.is_receiving_allowance);
                    setVal('has_health_insurance', result.has_health_insurance);
                    setSelect('other_id_available', result.other_id_available);
                    setSelect('other_id_type', result.other_id_type);
                    setVal('other_id_name', result.other_id_name);
                    setVal('other_id_number', result.other_id_number);

                    // 4. Nominee
                    setVal('nominee_zanid', result.nominee_zanid);
                    setVal('nominee_first_name', result.nominee_first_name);
                    setVal('nominee_last_name', result.nominee_last_name);
                    setVal('nominee_gender', result.nominee_gender);
                    setVal('nominee_rel_benf', result.nominee_rel_benf);
                    setVal('nominee_mobile', result.nominee_mobile);
                    setSelect('nominee_region', result.nominee_region);
                    setTimeout(() => {
                        setVal('nominee_district', result.nominee_district);
                        if (typeof window.filterNomShehias === 'function') {
                            window.filterNomShehias();
                        }
                        var nomShehiaEl = document.getElementById('nominee_shehia');
                        if (nomShehiaEl) nomShehiaEl.value = "";
                        var nomSearchInp = document.getElementById('nominee_shehia_search_input');
                        if (nomSearchInp) nomSearchInp.value = "";
                        var nomClear = document.getElementById('nominee_shehia_clear_btn');
                        if (nomClear) nomClear.style.display = 'none';
                    }, 120);
                    setVal('nominee_post_code', result.nominee_post_code);
                    setVal('nominee_house_street', result.nominee_house_street);

                    // 5. Pension
                    setSelect('other_pension', result.other_pension);
                    setVal('scheme_name', result.scheme_name);

                    // 6. Payment
                    setSelect('payment_mode', result.payment_mode);
                    setVal('bank_name', result.bank_name);
                    setVal('account_num', result.account_num);
                    setVal('account_name', result.account_name);
                    setVal('mobile_wallet', result.mobile_wallet);

                    // 7. Attachments
                    setImg('beneficiary_image', result.beneficiary_image);
                    setImg('nominee_image', result.nominee_image);
                    setImg('zan_image', result.zan_image);

                    statusDiv.innerText = "Found!";
                    statusDiv.style.color = "green";
                    var submitBtn = document.getElementById('beneficiary_submit');
                    if (submitBtn) submitBtn.disabled = false;
                } else if (data.result && data.result.status === 'ALREADY_EXISTS') {
                    statusDiv.innerText = data.result.message;
                    statusDiv.style.color = "red";
                    var submitBtn = document.getElementById('beneficiary_submit');
                    if (submitBtn) submitBtn.disabled = true;
                    // Do not auto-fill
                } else if (data.result && data.result.status === 'NOT_ELIGIBLE') {
                    statusDiv.innerText = data.result.message;
                    statusDiv.style.color = "red";
                    var submitBtn = document.getElementById('beneficiary_submit');
                    if (submitBtn) submitBtn.disabled = true;
                } else {
                    statusDiv.innerText = (data.result && data.result.message) || "Not found";
                    statusDiv.style.color = "red";
                    var submitBtn = document.getElementById('beneficiary_submit');
                    if (submitBtn) submitBtn.disabled = true;
                }
            })
            .catch(error => {
                console.error('Error:', error);
                statusDiv.innerText = "Error searching Zan ID";
                statusDiv.style.color = "red";
            });
        });
    }

    function toggleDisabilityType() {
        var disSelect = document.getElementById('disability');
        var container = document.getElementById('type_of_disability_container');
        var typeInput = document.getElementById('type_of_disability');
        if (disSelect && container) {
            if (disSelect.value === 'yes') {
                container.style.display = 'block';
            } else {
                container.style.display = 'none';
                if (typeInput) typeInput.value = '';
            }
        }
    }
    var disSelect = document.getElementById('disability');
    if (disSelect) {
        disSelect.addEventListener('change', toggleDisabilityType);
        toggleDisabilityType();
    }
});


document.addEventListener("DOMContentLoaded", function() {
    try {
        // Try by ID first, then by name as fallback
        var regionSelect = document.getElementById('ben_region') || document.querySelector('select[name="region"]');
        var districtSelect = document.getElementById('ben_district') || document.querySelector('select[name="district"]');
        var shehiaSelect = document.getElementById('street2') || document.querySelector('select[name="street2"]');

        if (!regionSelect || !districtSelect) {
            console.error("Region or District elements NOT FOUND.");
            return;
        }

        // Clone allowed options (simple way in vanilla)
        var allDistricts = Array.from(districtSelect.options).map(function(opt) {
            return { 
                text: opt.text, 
                value: opt.value, 
                dCode: opt.getAttribute('data-district-code'),
                regionId: opt.getAttribute('data-region-id')
            };
        });

        // Clone allowed shehias
        var allShehias = [];
        if (shehiaSelect) {
            allShehias = Array.from(shehiaSelect.options).map(function(opt) {
                return {
                    text: opt.text,
                    value: opt.value,
                    shehiaId: opt.getAttribute('data-shehia-id'),
                    districtId: opt.getAttribute('data-district-id'),
                    regionId: opt.getAttribute('data-region-id')
                };
            });
        }

        // Searchable Shehia elements
        var shehiaSearchInput = document.getElementById('shehia_search_input');
        var shehiaDropdownMenu = document.getElementById('shehia_dropdown_menu');
        var shehiaClearBtn = document.getElementById('shehia_clear_btn');
        var shehiaDropdownToggle = document.getElementById('shehia_dropdown_toggle');
        var currentActiveIndex = -1;

        function escapeRegExp(string) {
            return (string || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        }

        function escapeHtml(str) {
            return (str || '').replace(/[&<>'"]/g, function(tag) {
                return { '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag;
            });
        }

        function closeShehiaDropdown() {
            if (shehiaDropdownMenu) {
                shehiaDropdownMenu.style.display = 'none';
                currentActiveIndex = -1;
            }
        }

        function setActiveItem(idx, items) {
            if (!items || items.length === 0) return;
            items.forEach(function(el, i) {
                if (i === idx) {
                    el.style.backgroundColor = '#e9ecef';
                    el.scrollIntoView({ block: 'nearest' });
                } else if (shehiaSelect && shehiaSelect.value === el.getAttribute('data-value')) {
                    el.style.backgroundColor = '#e7f1ff';
                } else {
                    el.style.backgroundColor = '#fff';
                }
            });
            currentActiveIndex = idx;
        }

        function selectShehia(val) {
            if (shehiaSelect) shehiaSelect.value = val;
            if (shehiaSearchInput) {
                shehiaSearchInput.value = val;
                shehiaSearchInput.setCustomValidity('');
            }
            if (shehiaClearBtn) {
                shehiaClearBtn.style.display = val ? 'inline-block' : 'none';
            }
            closeShehiaDropdown();
            if (shehiaSelect) shehiaSelect.dispatchEvent(new Event('change'));
        }

        function renderShehiaDropdown(searchTerm) {
            if (!shehiaDropdownMenu) return;
            var term = (searchTerm || '').trim().toLowerCase();
            var selectedDistVal = districtSelect ? districtSelect.value : "";

            var matches = [];
            allShehias.forEach(function(s) {
                if (!s.value) return;
                if (!selectedDistVal || s.districtId === selectedDistVal) {
                    if (!term || s.text.toLowerCase().includes(term)) {
                        matches.push(s);
                    }
                }
            });

            shehiaDropdownMenu.innerHTML = '';
            currentActiveIndex = -1;

            if (!selectedDistVal) {
                var msg = document.createElement('div');
                msg.className = 'p-3 text-muted text-center';
                msg.innerHTML = '<small><i class="fa fa-info-circle me-1"></i>Please select a District first</small>';
                shehiaDropdownMenu.appendChild(msg);
            } else if (matches.length === 0) {
                var noMatch = document.createElement('div');
                noMatch.className = 'p-3 text-muted text-center';
                noMatch.innerHTML = '<small><i class="fa fa-search me-1"></i>No Shehia found matching "<b>' + escapeHtml(searchTerm) + '</b>"</small>';
                shehiaDropdownMenu.appendChild(noMatch);
            } else {
                matches.forEach(function(s, idx) {
                    var item = document.createElement('div');
                    item.className = 'shehia-dropdown-item';
                    item.style.padding = '8px 14px';
                    item.style.cursor = 'pointer';
                    item.style.fontSize = '14px';
                    item.style.borderBottom = '1px solid #f2f2f2';
                    item.setAttribute('data-value', s.value);

                    if (shehiaSelect && shehiaSelect.value === s.value) {
                        item.style.backgroundColor = '#e7f1ff';
                        item.style.fontWeight = '600';
                        item.style.color = '#0d6efd';
                    }

                    if (term) {
                        var regex = new RegExp('(' + escapeRegExp(term) + ')', 'gi');
                        item.innerHTML = escapeHtml(s.text).replace(regex, '<span style="background-color: #ffeeba; font-weight: bold; padding: 0 1px;">$1</span>');
                    } else {
                        item.textContent = s.text;
                    }

                    item.addEventListener('mouseenter', function() {
                        var allItems = shehiaDropdownMenu.querySelectorAll('.shehia-dropdown-item');
                        setActiveItem(idx, allItems);
                    });

                    item.addEventListener('mousedown', function(e) {
                        e.preventDefault();
                        selectShehia(s.value);
                    });

                    shehiaDropdownMenu.appendChild(item);
                });
            }

            shehiaDropdownMenu.style.display = 'block';
        }

        if (shehiaSearchInput) {
            shehiaSearchInput.addEventListener('input', function() {
                var term = this.value;
                if (shehiaClearBtn) {
                    shehiaClearBtn.style.display = term ? 'inline-block' : 'none';
                }
                renderShehiaDropdown(term);
            });

            shehiaSearchInput.addEventListener('focus', function() {
                renderShehiaDropdown(this.value);
            });

            shehiaSearchInput.addEventListener('click', function() {
                renderShehiaDropdown(this.value);
            });

            shehiaSearchInput.addEventListener('keydown', function(e) {
                var items = shehiaDropdownMenu ? shehiaDropdownMenu.querySelectorAll('.shehia-dropdown-item') : [];
                if (e.key === 'ArrowDown') {
                    e.preventDefault();
                    if (shehiaDropdownMenu && shehiaDropdownMenu.style.display === 'none') {
                        renderShehiaDropdown(this.value);
                        return;
                    }
                    if (items.length > 0) {
                        var next = (currentActiveIndex + 1) % items.length;
                        setActiveItem(next, items);
                    }
                } else if (e.key === 'ArrowUp') {
                    e.preventDefault();
                    if (items.length > 0) {
                        var prev = (currentActiveIndex - 1 + items.length) % items.length;
                        setActiveItem(prev, items);
                    }
                } else if (e.key === 'Enter') {
                    if (shehiaDropdownMenu && shehiaDropdownMenu.style.display !== 'none' && currentActiveIndex >= 0 && currentActiveIndex < items.length) {
                        e.preventDefault();
                        var val = items[currentActiveIndex].getAttribute('data-value');
                        selectShehia(val);
                    }
                } else if (e.key === 'Escape') {
                    closeShehiaDropdown();
                }
            });
        }

        if (shehiaDropdownToggle) {
            shehiaDropdownToggle.addEventListener('click', function(e) {
                e.preventDefault();
                if (shehiaDropdownMenu && shehiaDropdownMenu.style.display === 'block') {
                    closeShehiaDropdown();
                } else {
                    if (shehiaSearchInput) shehiaSearchInput.focus();
                    renderShehiaDropdown('');
                }
            });
        }

        if (shehiaClearBtn) {
            shehiaClearBtn.addEventListener('click', function(e) {
                e.preventDefault();
                selectShehia('');
                renderShehiaDropdown('');
                if (shehiaSearchInput) shehiaSearchInput.focus();
            });
        }

        document.addEventListener('click', function(e) {
            var container = document.getElementById('shehia_field_container');
            if (container && !container.contains(e.target)) {
                closeShehiaDropdown();
                if (shehiaSelect && shehiaSearchInput) {
                    if (shehiaSelect.value) {
                        shehiaSearchInput.value = shehiaSelect.value;
                        if (shehiaClearBtn) shehiaClearBtn.style.display = 'inline-block';
                    } else {
                        shehiaSearchInput.value = '';
                        if (shehiaClearBtn) shehiaClearBtn.style.display = 'none';
                    }
                }
            }
        });

        window.resetShehiaSearch = function() {
            if (shehiaSelect) shehiaSelect.value = '';
            if (shehiaSearchInput) {
                shehiaSearchInput.value = '';
                shehiaSearchInput.setCustomValidity('');
            }
            if (shehiaClearBtn) shehiaClearBtn.style.display = 'none';
            closeShehiaDropdown();
        };

        function filterShehias(preserveSelection) {
            if (!shehiaSelect) return;
            var selectedDistVal = districtSelect ? districtSelect.value : "";
            var currentShehiaVal = preserveSelection ? shehiaSelect.value : "";

            shehiaSelect.innerHTML = '';
            var defaultOpt = document.createElement('option');
            defaultOpt.value = "";
            defaultOpt.text = "Select Shehia";
            shehiaSelect.appendChild(defaultOpt);

            var matchingCount = 0;
            allShehias.forEach(function(s) {
                if (!s.value) return; // Skip original default
                if (!selectedDistVal || s.districtId === selectedDistVal) {
                    matchingCount++;
                    var opt = document.createElement('option');
                    opt.value = s.value;
                    opt.text = s.text;
                    opt.setAttribute('data-shehia-id', s.shehiaId);
                    opt.setAttribute('data-district-id', s.districtId);
                    opt.setAttribute('data-region-id', s.regionId);
                    if (currentShehiaVal && s.value === currentShehiaVal) {
                        opt.selected = true;
                    }
                    shehiaSelect.appendChild(opt);
                }
            });

            if (preserveSelection && currentShehiaVal) {
                selectShehia(currentShehiaVal);
            } else {
                if (shehiaSelect) shehiaSelect.value = '';
                if (shehiaSearchInput) {
                    shehiaSearchInput.value = '';
                    if (!selectedDistVal) {
                        shehiaSearchInput.placeholder = "Select District first...";
                    } else {
                        shehiaSearchInput.placeholder = "Type to search Shehia (" + matchingCount + " available)...";
                    }
                }
                if (shehiaClearBtn) shehiaClearBtn.style.display = 'none';
            }
            closeShehiaDropdown();
        }

        // Expose globally for API callbacks
        window.filterShehias = function() {
            filterShehias(false);
        };

        function filterDistricts() {
            var selectedVal = regionSelect.value; // ID

            // Clear and Rebuild
            var currentVal = districtSelect.value;
            districtSelect.innerHTML = ''; // clear

            // Always add default Select option
            var defaultOpt = document.createElement('option');
            defaultOpt.value = "";
            defaultOpt.text = "Select";
            districtSelect.appendChild(defaultOpt);

            allDistricts.forEach(function(d) {
                if (d.value === "") return; // Skip original default

                // Logic: Show if no region selected OR d.regionId matches selectedVal
                if (!selectedVal || d.regionId === selectedVal) {
                    var opt = document.createElement('option');
                    opt.value = d.value;
                    opt.text = d.text;
                    opt.setAttribute('data-district-code', d.dCode);
                    opt.setAttribute('data-region-id', d.regionId);
                    if (d.value === currentVal) opt.selected = true;
                    districtSelect.appendChild(opt);
                }
            });

            filterShehias(false);
        }

        regionSelect.addEventListener('change', filterDistricts);
        districtSelect.addEventListener('change', function() {
            filterShehias(false);
        });

        // Trigger initial
        if (regionSelect.value) {
            filterDistricts();
        }
        if (districtSelect.value) {
            filterShehias(true);
        }

        // Form submit validation for searchable Shehia
        var form = document.querySelector('form.s_website_form') || document.querySelector('form');
        if (form) {
            form.addEventListener('submit', function(e) {
                if (shehiaSearchInput && shehiaSelect) {
                    if (!shehiaSelect.value || shehiaSearchInput.value !== shehiaSelect.value) {
                        shehiaSearchInput.setCustomValidity('Please select a Shehia from the list');
                        shehiaSearchInput.reportValidity();
                        e.preventDefault();
                        return false;
                    } else {
                        shehiaSearchInput.setCustomValidity('');
                    }
                }
            });
        }

    } catch (e) {
        console.error(e);
    }
});

(function() {
    var waitInterval = setInterval(function() {
        if (typeof window.validateForm === 'function') {
            clearInterval(waitInterval);
            var originalValidateForm = window.validateForm;

            window.validateForm = function(isCreateForm) {
                var mobileVisual = document.getElementById('mobile_visual');
                var nomineeVisual = document.getElementById('nominee_mobile_visual');
                var benPhoneRegex = /^[67][0-9]{8}$/;   // Beneficiary: starts with 6/7, exactly 9 digits
                var phoneRegex = /^[67][0-9]*$/;         // Nominee: starts with 6/7, no length limit
                var errors = [];

                // Reset previous invalid states
                if (mobileVisual) mobileVisual.classList.remove('is-invalid');
                if (nomineeVisual) nomineeVisual.classList.remove('is-invalid');

                var mobileErrDiv = document.getElementById('mobile_error');
                var nomineeErrDiv = document.getElementById('nominee_mobile_error');
                if (mobileErrDiv) mobileErrDiv.style.display = 'none';
                if (nomineeErrDiv) nomineeErrDiv.style.display = 'none';

                // Validate beneficiary phone (if filled)
                if (mobileVisual && mobileVisual.value.length > 0) {
                    if (!benPhoneRegex.test(mobileVisual.value)) {
                        errors.push({field: mobileVisual, errId: 'mobile_error', section: 'demographic', label: 'Beneficiary Mobile', msg: ' must start with 6 or 7 and be 9 digits'});
                    }
                }

                // Validate nominee phone (if filled)
                if (nomineeVisual && nomineeVisual.value.length > 0) {
                    if (!phoneRegex.test(nomineeVisual.value)) {
                        errors.push({field: nomineeVisual, errId: 'nominee_mobile_error', section: 'nominee_info', label: 'Nominee Mobile', msg: ' must start with 6 or 7'});
                    }
                }

                if (errors.length > 0) {
                    var messages = errors.map(function(err) { return err.label + err.msg; });
                    alert(messages.join('\n'));

                    // Show error styling
                    errors.forEach(function(err) {
                        err.field.classList.add('is-invalid');
                        var div = document.getElementById(err.errId);
                        if (div) div.style.display = 'block';
                    });

                    // Expand section for the FIRST error
                    var firstErr = errors[0];
                    var section = document.getElementById(firstErr.section);
                    if (section && !section.classList.contains('show')) {
                        var accordionButton = document.querySelector('[data-bs-target="#' + firstErr.section + '"]');
                        if (accordionButton) accordionButton.click();
                    }

                    firstErr.field.scrollIntoView({behavior: 'smooth', block: 'center'});
                    firstErr.field.focus();
                    return false;
                }

                // If no phone errors, run the original required validation
                return originalValidateForm(isCreateForm);
            };
        }
    }, 100);
})();

input.oninput:
this.value = this.value.replace(/[^0-9]/g, '');
var fullVal = '+255' + this.value;
document.getElementById('mobile').value = fullVal;
var errDiv = document.getElementById('mobile_error');
if (this.value.length > 0 && !/^[67]/.test(this.value)) {
    if (errDiv) errDiv.style.display = 'block';
    this.classList.add('is-invalid');
} else {
    if (errDiv) errDiv.style.display = 'none';
    this.classList.remove('is-invalid');
}

div.script:
document.addEventListener("DOMContentLoaded", function() {
    try {
        // Try by ID first, then by name as fallback
        var regionSelect = document.getElementById('ben_region') || document.querySelector('select[name="region"]');
        var districtSelect = document.getElementById('ben_district') || document.querySelector('select[name="district"]');

        if (!regionSelect || !districtSelect) {
            console.error("Region or District elements NOT FOUND.");
            return;
        }

        // Clone allowed options (simple way in vanilla)
        var allDistricts = Array.from(districtSelect.options).map(function(opt) {
            return { 
                text: opt.text, 
                value: opt.value, 
                dCode: opt.getAttribute('data-district-code'),
                regionId: opt.getAttribute('data-region-id')
            };
        });

        function filterDistricts() {
            var selectedVal = regionSelect.value; // ID

            // Clear and Rebuild
            var currentVal = districtSelect.value;
            districtSelect.innerHTML = ''; // clear

            allDistricts.forEach(function(d) {
                // Logic: Show if no region selected OR d.value is empty (Select) OR code is valid
                // Note: selectedVal is string, regionId is string.
                if (!selectedVal || d.value === "" || d.regionId === selectedVal) {
                    var opt = document.createElement('option');
                    opt.value = d.value;
                    opt.text = d.text;
                    opt.setAttribute('data-district-code', d.dCode);
                    opt.setAttribute('data-region-id', d.regionId);
                    if (d.value === currentVal) opt.selected = true;
                    districtSelect.appendChild(opt);
                }
            });
        }

        regionSelect.addEventListener('change', filterDistricts);

        // Trigger initial
        if (regionSelect.value) {
            filterDistricts();
        }

    } catch (e) {
        console.error(e);
    }
});

document.addEventListener("DOMContentLoaded", function() {
    function checkFormValidity() {
        var submitBtn = document.getElementById('beneficiary_submit');
        if (!submitBtn) return;

        var isValid = true;
        // Find all required inputs
        var requiredInputs = document.querySelectorAll('input[required], select[required], textarea[required]');
        for (var i = 0; i < requiredInputs.length; i++) {
            var input = requiredInputs[i];
            if (input.disabled) continue;
            if (!input.value || input.value.trim() === "") {
                isValid = false;
                break;
            }
            if ((input.type === 'checkbox' || input.type === 'radio') && !input.checked) {
                isValid = false;
                break;
            }
        }
        submitBtn.disabled = !isValid;
    }

    // Listen to input and change events
    document.addEventListener('input', checkFormValidity);
    document.addEventListener('change', checkFormValidity);

    // Initial check
    setTimeout(checkFormValidity, 500);
});

xpath.script:
document.addEventListener("DOMContentLoaded", function() {
    // Disable all form inputs
    var inputs = document.querySelectorAll('input, select, textarea');
    for (var i = 0; i < inputs.length; i++) {
        inputs[i].disabled = true;
        inputs[i].style.backgroundColor = "#e9ecef"; // Bootstrap disabled gray
        inputs[i].removeAttribute('required');
    }

    // Disable custom dropdown buttons
    document.querySelectorAll('.custom-multi-select .dropdown-toggle').forEach(function(button) {
        button.disabled = true;
        button.style.backgroundColor = "#e9ecef";
    });

    // Hide camera and search buttons
    document.querySelectorAll('.open-cam, #zan_id_search, #nominee_zan_id_search').forEach(function(button) {
        button.style.display = 'none';
    });
});
